(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const tab = (name) => [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes(name));
  const out = { steps: [] };
  try {
    // ① 建卍解作品
    const nameInput = document.querySelector('.tb-card .tb-input');
    if (!nameInput) { out.error = '新建面板没打开'; return JSON.stringify(out); }
    setV(nameInput, '卍解测试·四件套齐全');
    [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
    await sleep(300);
    [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
    for (let i = 0; i < 20; i++) { await sleep(500); if (document.querySelector('.pc-wrap')) break; }
    out.opened = document.querySelector('.pj-title')?.textContent || null;

    // ② 程序代码
    [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
    await sleep(700);
    const inputs = [...document.querySelectorAll('.pc-input')];
    setV(inputs[0], 'main.c');
    setV(inputs[1], '主程序');
    setV(document.querySelector('.pc-textarea'), '#include "stm32f10x.h"\n// 让 LED 闪起来\nint main(void) { return 0; }\n');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
    await sleep(2000);
    out.code = document.querySelector('.pc-item-name')?.textContent || null;

    // ③ 接线表两行
    tab('接线表')?.click();
    await sleep(600);
    const addPin = async (m, p, b, n) => {
      const ins = [...document.querySelectorAll('.pc-inline-form .pc-input')];
      setV(ins[0], m); setV(ins[1], p); setV(ins[2], b); setV(ins[3], n);
      [...document.querySelectorAll('.pc-btn-primary')].find((x) => x.textContent.includes('加一行'))?.click();
      await sleep(1500);
    };
    await addPin('超声波 HC-SR04', 'TRIG', 'PA0', '触发脚');
    await addPin('超声波 HC-SR04', 'ECHO', 'PA1', '回波脚，5V 要分压');
    out.pinRows = document.querySelectorAll('.pc-table tbody tr').length;

    // ④ 调试记录
    tab('调试记录')?.click();
    await sleep(600);
    setV(document.querySelector('.pc-input-full'), '下载不进程序');
    setV(document.querySelector('.pc-textarea-sm'), 'Keil 里要选对芯片型号，ST-Link 的 SWD 四根线别少接地');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('记下来'))?.click();
    await sleep(1600);
    out.debugs = document.querySelectorAll('.pc-debug').length;

    // ⑤ 开发环境
    tab('开发环境')?.click();
    await sleep(600);
    setV(document.querySelector('.pc-textarea'), 'Keil µVision5（MDK-ARM）+ STM32F10x 器件包，ST-Link V2 下载');
    [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.trim() === '保存')?.click();
    await sleep(1600);
    out.envMsg = document.querySelector('.pc-msg')?.textContent || null;

    // ⑥ 导出
    let captured = null;
    const orig = URL.createObjectURL.bind(URL);
    URL.createObjectURL = (b) => { captured = b; return orig(b); };
    [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('保存作品文件'))?.click();
    for (let i = 0; i < 20 && !captured; i++) await sleep(500);
    URL.createObjectURL = orig;
    out.exported = !!captured;
    if (captured) {
      const buf = new Uint8Array(await captured.arrayBuffer());
      let bin = '';
      const chunk = 0x8000;
      for (let i = 0; i < buf.length; i += chunk) bin += String.fromCharCode(...buf.subarray(i, i + chunk));
      out.bytes = buf.length;
      out.b64 = btoa(bin);
    }
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
